/* Display-only planet abbreviations; calculation IDs and saved inputs stay intact. */
(()=>{'use strict';const rows=[['Su','Sun','सू','रवी','रवि','सूर्य'],['Mo','Moon','चं','चंद्र'],['Ma','Mars','मं','मंगळ','मंगल'],['Me','Mercury','बु','बुध'],['Ju','Jupiter','गु','गुरु','गुरू','बृहस्पति'],['Ve','Venus','शु','शुक्र'],['Sa','Saturn','श','शनि','शनी'],['Ra','Rahu','रा','राहू','राहु'],['Ke','Ketu','के','केतू','केतु']],lookup=new Map();for(const r of rows)for(const name of [r[0],r[1],...r.slice(3)])lookup.set(name,r);const escaped=[...lookup.keys()].filter(name=>!rows.some(r=>r[0]===name)).sort((a,b)=>b.length-a.length).join('|'),pattern=new RegExp('(?<![\\p{L}\\p{M}])('+escaped+')(?![\\p{L}\\p{M}])','gu'),originals=new WeakMap();
function label(id,lang=window.KPPreferences?.get().language){const r=lookup.get(id);return r?(lang==='marathi'||lang==='hindi'?r[2]:lang==='bilingual'?r[0]+' · '+r[2]:r[0]):id;}
function format(text,lang){if(window.KPPreferences?.get().planetNotation!=='short')return text;return String(text).replace(pattern,name=>{const r=lookup.get(name);return lang==='bilingual'?(name===r[1]?r[0]:r[2]):label(name,lang);});}
function protectedText(root,lang){const owner=root.ownerDocument||root,walker=owner.createTreeWalker(root,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);for(const n of nodes){const e=n.parentElement;if(!e?.closest('[data-no-localize]')||e.closest('script,style,input,textarea,[contenteditable],[data-private-calculation],#setting-language'))continue;const previous=originals.get(n),source=previous?.rendered===n.nodeValue?previous.source:n.nodeValue,next=format(source,lang);if(next!==n.nodeValue)n.nodeValue=next;originals.set(n,{source,rendered:next});}}
window.KPPlanetNotation=Object.freeze({label,format,protectedText});})();
